// The "Try a sample" collection: regenerated byte for byte, built from the
// pinned sister-site hive, synthetic and harmless, and read the way the story
// says (exactly which detections, changes and flags).
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { beforeAll, describe, expect, it } from "vitest";
import { collect } from "@/lib/intake/collect";
import { md5, sha1, sha256 } from "@/lib/defender/hash";
import { buildRecoveryZip } from "@/lib/defender/recover";
import type { Analysis } from "@/lib/defender/types";
import { M64, PUA, sampleFiles, sampleZip } from "@/scripts/make-samples";
import { analyzeAll, file } from "./helpers";

const DIR = join(process.cwd(), "public/samples");
const SRC = join(process.cwd(), "scripts/sample-src");
const files = sampleFiles();
const manifest = JSON.parse(readFileSync(join(DIR, "manifest.json"), "utf8")) as { file: string; path: string; mtime: number }[];
let sample: Analysis;
beforeAll(async () => {
  sample = await analyzeAll(manifest.map((m) => ({ path: m.file, bytes: new Uint8Array(readFileSync(join(DIR, m.file))), mtime: m.mtime })));
});

const flagged = (a: Analysis) => [...a.detections, ...a.changes].filter((x) => x.flags.length).map((x) => `${"threatName" in x ? x.threatName : `${x.what} ${x.params.value ?? x.params.name ?? x.params.kind ?? ""}`}: ${x.flags.map((f) => `${f.code}:${f.severity}`).join(" ")}`).sort();

describe("sample", () => {
  it("is what the generator writes, byte for byte", () => {
    expect(manifest).toEqual(files.map((f) => ({ file: f.path, path: f.path.slice("FIN-WKS-07/C/".length), mtime: f.mtime })));
    for (const f of files) expect(new Uint8Array(readFileSync(join(DIR, f.path))), f.path).toEqual(f.bytes);
    expect(new Uint8Array(readFileSync(join(DIR, "FIN-WKS-07.zip")))).toEqual(sampleZip(files));
  });

  it("holds the pinned SOFTWARE hive unchanged", () => {
    const pins = [...readFileSync(join(SRC, "SOURCES.md"), "utf8").matchAll(/\| `([^`]+)` \| `([0-9a-f]{64})` \|/g)];
    expect(pins.length).toBe(1);
    const [, path, sha] = pins[0];
    const src = readFileSync(join(SRC, path));
    expect(createHash("sha256").update(src).digest("hex")).toBe(sha);
    expect(files.find((f) => f.path.endsWith("config/SOFTWARE"))!.bytes).toEqual(new Uint8Array(src));
  });

  it("is harmless: placeholder text, no EICAR string, no executable header", () => {
    const eicar = "EICAR-STANDARD-ANTIVIRUS-TEST-FILE";
    for (const f of [...files.map((x) => x.bytes), M64, PUA, new Uint8Array(readFileSync(join(DIR, "FIN-WKS-07.zip")))]) {
      expect(new TextDecoder("latin1").decode(f)).not.toContain(eicar);
      // Nor in UTF-16.
      expect(new TextDecoder("utf-16le").decode(f.subarray(0, f.length & ~1))).not.toContain(eicar);
    }
    for (const b of [M64, PUA]) {
      expect(new TextDecoder().decode(b.subarray(0, 40))).toMatch(/^SYNTHETIC PLACEHOLDER for /);
      expect(b[0] === 0x4d && b[1] === 0x5a).toBe(false);
    }
    // m64.exe is Disk Image Parser's placeholder: the same hashes on both sites.
    expect([md5(M64), sha1(M64), sha256(M64)]).toEqual(["2f5474b96b278c17fdf8bd4ab21497f8", "a8141a7c15c0ef03bb93b956deb3518236ea8760", "44391e6b73173c7608e4049a954e000bf33e7e84696d6b7bffc1265d517e896a"]);
  });

  it("reads every file as what it is", () => {
    expect(sample.files.map((f) => [f.role, f.status]).sort()).toEqual(
      [
        ["entry", "parsed"],
        ["entry", "parsed"],
        ["evtx", "parsed"],
        ["history", "parsed"],
        ["history", "parsed"],
        ["mpcmdrun", "parsed"],
        ["mpdetection", "parsed"],
        ["mplog", "parsed"],
        ["resourcedata", "parsed"],
        ["resourcedata", "parsed"],
        ["resources", "parsed"],
        ["resources", "parsed"],
        ["software", "parsed"],
      ].sort(),
    );
    expect(sample.files.every((f) => f.unparsedCount === 0 && !f.error)).toBe(true);
    expect(sample.events).toHaveLength(26);
    expect(sample.hosts.map((h) => [h.name, h.users, h.newest])).toEqual([["FIN-WKS-07", ["alice", "svc_backup"], Date.UTC(2026, 8, 14, 10, 15, 42, 118)]]);
  });

  it("tells the story", () => {
    const d = (n: string) => sample.detections.find((x) => x.threatName === n)!;
    expect(sample.detections.map((x) => x.threatName)).toEqual(["Backdoor:Win64/Gfxhelp.A", "Trojan:PowerShell/AmsiBypass.SY", "PUA:Win32/Convertly"]);
    const m64 = d("Backdoor:Win64/Gfxhelp.A");
    expect(m64).toMatchObject({ time: Date.UTC(2026, 8, 14, 10, 6, 51, 388), path: "C:\\Users\\svc_backup\\Downloads\\tools\\m64.exe", user: "FIN-WKS-07\\svc_backup", process: "C:\\Program Files\\7-Zip\\7zFM.exe", result: "done", quarantined: true, status: "Quarantined" });
    expect(m64.hashes).toEqual({ sha256: sha256(M64), sha1: sha1(M64), md5: md5(M64), from: ["quarantine", "history", "mplog"] });
    expect(m64.joins.map((j) => j.how)).toEqual(["same_detection_id", "history_detection_id", "history_quarantine_id", "mplog_threat_path_time", "mplog_threat_path_time", "sdn_same_path"]);
    const res = m64.quarantine[0].resources[0];
    expect(res.data).toMatchObject({ nameMatches: "content", owner: "S-1-5-21-3623811015-3361044348-30300820-1119", recovered: { size: 9216, sha256: sha256(M64) } });
    // No Zone.Identifier on the quarantined m64.exe; the PUA's, written by Edge, is there.
    expect(res.data!.zone).toBeUndefined();
    expect(d("PUA:Win32/Convertly").quarantine[0].resources[0].data!.zone).toMatchObject({ zoneId: "3", referrerUrl: "https://convertly.example/download", hostUrl: "https://downloads.convertly.example/ConvertlyPDF_Setup.exe" });
    const amsi = d("Trojan:PowerShell/AmsiBypass.SY");
    expect(amsi).toMatchObject({ amsi: true, result: "done", quarantined: false, status: "Blocked", source: { id: 10, name: "AMSI", from: "event" } });
    // Changes at the brief's times.
    const times = sample.changes.filter((c) => c.source === "event").map((c) => [c.what, new Date(c.time!).toISOString()]);
    expect(times).toEqual([
      ["rtp_enabled", "2025-11-03T09:52:10.204Z"],
      ["tamper_blocked", "2026-09-14T10:07:36.120Z"],
      ["exclusion_added", "2026-09-14T10:08:12.457Z"],
      ["exclusion_added", "2026-09-14T10:08:12.771Z"],
    ]);
    // alice's invoice was not detected, but MPLog saw it, with its hashes.
    expect(sample.detections.some((x) => /invoice/i.test(x.path))).toBe(false);
    expect(sample.mplog.find((m) => m.kind === "sdn" && /Invoice_2026-0914/.test(m.fields.Path))?.fields.Sha256).toMatch(/^[0-9a-f]{64}$/);
  });

  it("flags exactly these", () => {
    expect(flagged(sample)).toEqual([
      "Backdoor:Win64/Gfxhelp.A: exclusion_nearby:high downloads:low recent:low",
      "PUA:Win32/Convertly: downloads:low",
      "Trojan:PowerShell/AmsiBypass.SY: amsi:medium recent:low",
      "exclusion_added C:\\ProgramData\\Intel: exclusion_writable:high recent:low",
      "exclusion_added m64.exe: exclusion_near_detection:high exclusion_process_name:medium recent:low",
      "exclusion_present C:\\ProgramData\\Intel: exclusion_writable:high recent:low",
      "exclusion_present m64.exe: exclusion_near_detection:high exclusion_process_name:medium recent:low",
      "tamper_blocked 0x1: tamper_blocked:medium recent:low",
    ]);
  });

  it("recovers m64.exe as an encrypted ZIP only", () => {
    const rd = files.find((f) => /ResourceData/.test(f.path) && sample.quarantine.some((q) => q.resources.some((r) => r.data?.file === f.path && r.display.endsWith("m64.exe"))))!;
    const r = buildRecoveryZip(rd.bytes, { host: "FIN-WKS-07", path: "C:\\Users\\svc_backup\\Downloads\\tools\\m64.exe", resourceData: rd.path })!;
    expect(r.sha256).toBe(sha256(M64));
    expect(new TextDecoder("latin1").decode(r.zip)).not.toContain("SYNTHETIC PLACEHOLDER");
  });

  it("reads the same through the zip as from the loose files", async () => {
    const c = await collect([file("FIN-WKS-07.zip", new Uint8Array(readFileSync(join(DIR, "FIN-WKS-07.zip"))))]);
    expect(c.artifacts).toHaveLength(13);
    expect(c.artifacts.every((x) => !x.mtimeApprox)).toBe(true);
    const inputs = await Promise.all(c.artifacts.map(async (x) => ({ path: x.path, bytes: new Uint8Array(await x.file.arrayBuffer()), mtime: x.file.lastModified || null })));
    const viaZip = await analyzeAll(inputs);
    expect(flagged(viaZip)).toEqual(flagged(sample));
    expect(viaZip.hosts.map((h) => h.name)).toEqual(["FIN-WKS-07"]);
  });
});
